def shortest_path(graph, source, target):
    unvisited_nodes = [(0, source, [])]
    visited = set()
    shortest_path_for_target = float('inf')
    path_to_end = None
    shortest_found = False
    visited_edges = set()
    while not shortest_found:
        if not unvisited_nodes:
            return (shortest_path_for_target, path_to_end)
        distance, current_node, path = min(unvisited_nodes)
        unvisited_nodes.remove((distance, current_node, path))
        if current_node == target:
            path_to_end = path
            shortest_found = True
            distance = shortest_path_for_target
        visited.add(current_node)
