def reconstruct_path(graph: dict, distance: dict, source: str, target: list[str]) -> list:
    path_back = deque(maxlen=len(distance))
    cur_node_path = deque()
    while graph:
        min_dist, node = min(((distance[ncn], ncn) for ncn, dist in graph.items() if ncn not in cur_node_path and node == source))
        if min_dist > float('inf'):
            break
        cur_node_path.appendleft(node)
        path_back.appendleft(node)
        graph = {nc: d[nc] for nc, d in graph.items() if nc not in cur_node_path}
    cur_node_path.extend(graph.get(source))
    path_back.extend(cur_node_path)
    return list(path_back)
