        dist_to[current_node] = current_distance
        if current_node in graph:
            for neighbor_node, weight in list(graph.get(current_node, [])):
                new_dist_to = dist_to[current_node] + weight
                if new_dist_to < dist_to.get(neighbor_node, float('Inf')):
                    came_from[neighbor_node] = (current_node, weight)
                    del graph[neighbor_node][:]
                    heapq.heappush(queue, (new_dist_to, neighbor_node))
