            return path
        visited.add(path[-1])
        if not paths:
            return None
        current_path = paths.pop(0)
        for node, weight in graph[current_path[-1]]:
            if node not in visited:
                if len(current_path) != len(path):
                    new_path = list(current_path)
                    new_path.append(node)
                    paths.append(new_path)
                elif len(new_path) < len(path[:-1] + [node]):
                    return bfs(visited, paths[:])
                elif len(new_path[:-1]) == len(path[:-1] + [node]):
                    for _path in paths:
                        _len = len(_path)
                        _node, _wgt = (node, None)
                        if len(_path) and len(_path[:-1]) == _len:
                            _node = path[_node]
                            _wgt = None if len(_path[::2]) == _len // 2 else float('inf')
                        if not (visited and any((_visited[-1] == _node and (visited[_visited[-1]][1] == _wgt or visited[_visited[-1]][1] is float('inf')) for visited in paths[:-1]))):
