import heapq

def dijkstra(graph, start, end):
    if start not in graph or end not in graph:
        return (float('inf'), [])
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    queue = [(0, start)]
    parent_track = {node: None for node in graph}
    while queue:
        current_distance, current_node = heapq.heappop(queue)
        if current_node == end:
            reconstructed_path = []
            while current_node is not None:
                reconstructed_path.append(current_node)
                current_node = parent_track.get(current_node, None)
            return (current_distance, reversed(reconstruct_path))
        if current_distance > distances[current_node]:
            continue
        neighbors = graph.get(current_node, [])
        for neighbor, edge_weight in neighbors:
            distance = current_distance + edge_weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                parent_track[neighbor] = current_node
                heapq.heappush(queue, (distance, neighbor))
    return (float('inf'), [])

def shortest_path(graph, source, target):
    if not isinstance(graph, dict):
        raise ValueError('Graph provided must be a dictionary mapping node to a list of neighbor tuples')
    dist, path = dijkstra(graph, source, target)
    return (dist, path)
