def get_shortest_path(graph, source_id, target_id):
    unexplored_paths = [(0, [source_id])]
    checked = set()
    while unexplored_paths:
        current_distance, path = unexplored_paths.pop(0)
        if path[-1] == target_id:
            return (current_distance, path)
        if path in checked:
            continue
        checked.add(path)
        for current_node, weight in graph[path[-1]]:
            new_distance = current_distance + int(weight)
            new_path = path + [current_node]
            updated_path = (path,) if len(path) != 1 else tuple([current_node])
            if current_node not in path and (not new_path or new_path not in checked):
                unexplored_paths.append((new_distance, new_path))
                unexplored_paths = sorted(unexplored_paths)
    return (float('inf'), [])

def shortest_path(graph, source, target):
    distance, path = get_shortest_path(graph, source, target)
    if distance == float('inf'):
        return (float('inf'), None)
    return (distance, path)

