def shortest_path_dijkstra(graph, source, target):
    import heapq
    from heapq import heappop, heappush

    if not graph:
        return (float("inf"), None)

    # Dijkstra's algorithm
    # graph: a dict, where graph[start_node] is a list of tuples (next_node, edge_weight)
    # source and target are nodes
    if target not in graph:
        return (float("inf"), None)

    infinity = float('inf')
    distances = {node: infinity for node in graph}

    previous = {node: None for node in graph}

    distances[source] = 0
    priorityQueue = [(0, source)]

    while len(priorityQueue) > 0:
        currDistance, currentNode = heappop(priorityQueue)

        if currDistance > distances[currentNode]:
            # This path to node is farther than previously recorded
            # so just ignore the path and move on
            continue

        # Consider neighbors from node "currentNode" and check the path distance
        if not graph[currentNode]:
            # Node with no neighbors
            continue

        for nextNode, edge in graph[currentNode]:
            distanceToNextNode = currDistance + edge
            if distanceToNextNode < distances[nextNode]:
                distances[nextNode] = distanceToNextNode
                previous[nextNode] = currentNode

                # Add it back into the priority queue with a shorter distance
                heappush(priorityQueue, (distanceToNextNode, nextNode))

    # Construct the shortest path from "source" to "target"
    if previous[target]:
        result = [target]
        current = previous[target]
        while current:
            result.append(current)
            current = previous[current]
        result.reverse()
        return (distances[target], result)
    else:
        return (float("inf"), None)

