    distances = {node: float('inf') for nodes in graph for node in nodes}
    distances[source] = 0
    visited = {}

    # Priority queue: [(distance from source, node)]
    queue = deque([[0, source]])

    while queue:
        (distanceSoFar, current) = queue.popleft()
        if current == target:
            path = []
            while current:
                path.append(current)
                current = visited[current]
            return (distances[target], path[::-1])

        for neighbor, edgeWeight in graph[current]:
            distanceToNeighbor = distanceSoFar + edgeWeight
            if neighbor not in distances or distanceToNeighbor < distances[neighbor]: # Relaxation
                distances[neighbor] = distanceToNeighbor
                visited[neighbor] = current
                queue.append([distanceToNeighbor, neighbor])

    # Target unreachable.
    return (float('inf'), None)

