def dijkstra_algorithm(graph, start_node, target_node):
    import heapq
    to_explore = [(0, start_node, (start_node,))]
    visited = {}
    known_cost_to = {start_node: 0}
    while to_explore:
        _, node, path = heapq.heappop(to_explore)
        if target_node is not None and node == target_node and (known_cost_to[node] != float('inf')):
            return (known_cost_to[target_node], path)
        if node not in visited:
            visited[node] = (known_cost_to[node], path)
            for neighbor_node, weight in graph.get(node, ()):
                cost_to_neighbor = known_cost_to[node] + weight
                if cost_to_neighbor not in known_cost_to or cost_to_neighbor > known_cost_to[neighbor_node]:
                    old_distance = known_cost_to.get(neighbor_node, float('inf'))
                    if cost_to_neighbor < old_distance:
                        known_cost_to[neighbor_node] = cost_to_neighbor
                        to_explore.extend(((distance + weight, new_path + (neighbor_node,), (new_path[1] + 1, neighbor_node)) for new_path, distance in enumerate(to_explore) for weight, neighbor_node, _ in graph.get(node, ())))
    return (float('inf'), None)

