        while queue:
            prev, vertex, path = queue.popleft()
            # Update path distance only if the new path is optimal
            if vertex == target and path[-1] == target and unexplored_distance >= len(path):
                unexplored_distance = len(path)
                distance[vertex] = unexplored_distance
                previous_nodes = deque(reversed([x[1] for x in path[::-1]]))
                visited |= {prev}
                path.clear()
                # Re-traverse the path backwards
                while not next_node := previous_nodes.popleft():
                    path.insert(0, next_node)
                return distance[target], path

            if vertex in visited:
                continue
            path.append((prev, vertex[0]))
            distance[vertex] = float("inf")
            unexplored_distance = max(unexplored_distance, len(path)) if unexplored_distance is not len(path) else unexplored_distance
            for adjacent, weight in graph[vertex]:
                visited.add(vertex)
                neighbor_node = None, vertex[0] + vertex[1], adjacent[0] + weight
                # If it's a direct connection or the neighbor of a previously visited node
                if not neighbor_node in path and vertex != None:
                    if (prev == None and neighbor_node[2] not in {neighbor_node[1]: 0 for neighbor_node in path[::-1]}.keys()):
                         queue.append((vertex,node) + tuple(path+[neighbor_node]))
