def shortest_path(graph, source, target):
    # Define a generator function to generate unique ids for each edge
    def unique_id(edges):
        for i, (_, _, d) in enumerate(edges):
            yield (i, d)

    # Dijkstra's Shortest Path Algorithm
    # Graph: Dict, Source: Node, Target
    edges = list(unique_id(((u, v, w) for u, vs in graph.items() for v, w in vs)))
    inf = math.inf

    # Initial distance dictionary, set initial distance as infinity
    distance = {v: inf for w, v, _ in edges}  
    distance[source] = 0

    # The predecessor for each node, used in the path retrieval
    predecessors = {n: None for w, n, _ in edges}

    # We keep the nodes to be expanded in a priority queue with the initial distance
    expanded = deque([((node, 0), i) for i, (_, node, d) in enumerate(edges)])

    # Process the graph
    while expanded:
        # The minimum of the distance values (node, i), which is of the format (node, d), with the current shortest paths so far 
        current_node = min(expanded, key=lambda x: x[0][1], default=None)

        if not current_node or not current_node[0] in graph:
            return (inf, [])

        node, curr_dist = current_node[0]
        i = current_node[1]
        del expanded[i]

        if node == target:
            path = deque()
            current_node = (node, d[i])
            while node:
                path.appendleft(node)
                node = predecessors[node]

            return (curr_dist, list(path))

        neighbors_weights = []
        for neighbor, i_neighbor in zip(
            graph.get(node),
            range(len(edges)),
        ):

            neighbor = neighbor[1] 

            # If current node's neighbor hasn't been visited, we can calculate its cost.
            if distance[neighbor] is inf:
                weight = i + 1 if len(neighbors_weights) >= i else i_neighbor
                weight = edges[i][2] - weight

                # Update distance and the predecessors
                neighbors_weights.append((neighbor, weight))
        for neighbor, cost in neighbors_weights:
            new_cost = curr_dist + cost
            if new_cost < distance[neighbor]:
                distance[neighbor] = new_cost
                predecessors[neighbor] = node

                # Update the priority queue 
                for _j in range(i+1, len(edges)):
                    if edges[_j][2] == cost + len(neighbors_weights) + 1:
                        break                    

                	expended.insert(_j, ((neighbor, new_cost), _j))

        for _j in (i+1, len(edges)):
            if edges[_j][2] == cost + len(neighbors_weights) + 1:
                del edges[_j]

    return (inf, [])  # unreachable

