import heapq

def shortest_path(graph, source, target):
    """
    Finds the shortest path from source to target node in a weighted graph.

    :param graph: dict mapping each node to the list of neighbours and edge weights
    :param source: starting node
    :param target: ending node
    :return: a tuple (distance, path) where path is the list of nodes from source to target, or (float('inf'), None) if unreachable
    """

    # Priority queue: [(node, distance from 'source', previously seen node in the path, predecessor in the path)]
    priority_queue = [[0, source, source]]

    distances = {node: float('inf') for node in graph}
    distances[source] = 0  # distance from source to source is 0
    seen = set()

    while priority_queue:
        current_dist, node, last_visited = heapq.heappop(priority_queue)

        if node == target:
            return (current_dist, [target] + [last_visited for last_visited in distances[source] if last_visited]))

        if node in seen:
            continue
        seen.add(node)

        for neighbor, weight  in graph.get(node, []):
            new_dist = current_dist + weight
            if distances[node] <= new_dist:
                continue

            if (dist:= new_dist) < current_dist:
            # Update the distance and push to queue 
                distances[neighbor] = dist
                heapq.heappush(priority_queue, [dist, neighbor, node])

    return (float('inf'), None)

