import math

def dijkstra(graph, source):
    # Initialize priority queue with (0, source)
    priority_queue = [(0, source)]
    # Track distances of each node starting from source
    distances = {node: math.inf for node in graph}
    distances[source] = 0
    # Track the previous node for the shortest path reconstruction
    path_to = {src: None for src in graph}
    visited = set()

    while priority_queue:
        current_distance, current_node = min(priority_queue)

        if current_node == 'target':
            path = reconstruct_path(path_to, 'target')
            break

        visited.add(current_node)

        neighbors = graph[current_node]

        # Relax edges
        for neighbor in neighbors:
            new_distance = current_distance + neighbor[1]

            if neighbor[0] not in visited and new_distance < distances[neighbor[0]]:
                distances[neighbor[0]] = new_distance
                priority_queue.append((new_distance, neighbor[0]))
                path_to[neighbor[0]] = current_node

                # Re-organize the priority queue after an update (heap)
                for i, (dist_from_current, node) in enumerate(priority_queue):
                    if node == neighbor[0]:
                        priority_queue[i] = (new_distance, neighbor[0])
                        heapq.nlargest(len(priority_queue[i:-1]))

        for _, next_node in neighbors:
            if next_node in visited:
                continue

            heapq.heappop(priority_queue)  # Remove the node that got popped out

            for i, (new_dist, node) in list(enumerate(priority_queue)):
                if node == next_node:
                    del priority_queue[i]  # Re-insert with new dist

            priority_queue.sort()

    path = reconstruct_path(path_to, 'target') if path_to['target'] else None

    if path:
        return (distances[path[-1]], (path, distances))
    else:
        return (math.inf, None)

def reconstruct_path(to, node):
    path = [node]

    while to[node] is not None:
        node = to[node]
        path.append(node)

    path.reverse()

    return path

