def shortest_path(graph, source, target):
    # Initialization
    if source not in graph:
        return (float("inf"), None)
    if target not in graph:
        return (float("inf"), None)

    # Step 1: Preparing the priority queue and the visited dictionary for breadth-first searching starting from source
    visited = set()
    to_visit = [(0, [source])]
    path_length = {}

    # Step 2: Execute BFS until all vertices are visited or until destination node has been reached
    while to_visit and target not in visited:
        cost, path = heapq.heappop(to_visit)
        node = path[-1]

        if node not in visited:
            for neighbor, weight in graph[node]:
                if neighbor not in visited:
                    new_cost = cost + weight
                    new_path = path + [neighbor]

                    if neighbor not in visited or new_cost < path_length[neighbor]:
                        path_length[neighbor] = new_cost
                        heapq.heappush(to_visit, (new_cost, new_path))
            visited.add(node)

    if target not in path_length:
        return (float("inf"), None)
    else:
        shortest_weight = path_length[target]
        return (shortest_weight, path + [target])

