def shortest_path(graph, source, target):
    if target not in graph:
        return (float('inf'), None)
    node_to_dist_from_source = {source: (0, None)}
    heap = []
    for neighbour, weight in graph.get(source, []):
        heapq.heappush(heap, (0 + weight, source, neighbour))
        node_to_dist_from_source[neighbour] = (0, source)
    while heap:
        current_distance_sum, predecessor, current_node = heapq.heappop(heap)
        if current_node == target:
            path = [target]
            parent = node_to_dist_from_source.pop(current_node)
            while parent[1]:
                path.insert(0, parent[1])
                parent = node_to_dist_from_source.get(parent[1])
            path = [source] + path
            return (current_distance_sum, path)
        if current_node not in graph:
            continue
        current_cost_sum, predecessor_current_node = node_to_dist_from_source[current_node]
        for neighbour, weight in graph.get(current_node, []):
            new_cost_sum = current_cost_sum + weight
            if current_node == predecessor_current_node and new_cost_sum > current_distance_sum and (neighbour not in (source, target)):
                continue
            elif neighbor not in node_to_dist_from_source or new_cost_sum < node_to_dist_from_source[neighbour][0]:
                heapq.heappush(heap, (new_cost_sum, current_node, neighbor))
                node_to_dist_from_source[neighbor] = (new_cost_sum, current_node)
                node_to_dist_from_source[neighbor] = (min(new_cost_sum, node_to_dist_from_source[neighbor][0]), current_node)
    return (float('inf'), None)

